class Solution:
    def maxMinScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def ok(t):
            if t == 0:
                return True
            extra = 0
            for p in points:
                extra += (t + p - 1) // p - 1
                if extra > m:
                    return False
            return n + 2 * extra - (1 if extra > 0 else 0) <= m

        lo, hi = 0, max(points) * m
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if ok(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

