class Solution {
    public long maxMinScore(int[] points, int m) {
        int n = points.length;
        long mm = m;
        int mx = 0;
        for (int p : points) mx = Math.max(mx, p);
        long lo = 0, hi = (long) mx * mm;
        while (lo < hi) {
            long mid = lo + (hi - lo + 1) / 2;
            if (ok(points, n, mid, mm)) lo = mid;
            else hi = mid - 1;
        }
        return lo;
    }
    private boolean ok(int[] points, int n, long t, long m) {
        if (t == 0) return true;
        long extra = 0;
        for (int p : points) {
            extra += (t + p - 1) / p - 1;
            if (extra > m) return false;
        }
        return n + 2 * extra - (extra > 0 ? 1 : 0) <= m;
    }
}

