var maxMinScore = function(points, m) {
    const n = points.length;
    const ok = (t) => {
        if (t === 0) return true;
        let extra = 0;
        for (const p of points) {
            extra += Math.ceil(t / p) - 1;
            if (extra > m) return false;
        }
        return n + 2 * extra - (extra > 0 ? 1 : 0) <= m;
    };
    let lo = 0, hi = Math.max(...points) * m;
    while (lo < hi) {
        const mid = lo + Math.floor((hi - lo + 1) / 2);
        if (ok(mid)) lo = mid;
        else hi = mid - 1;
    }
    return lo;
};
